package com.decisionhub.backend.service.impl;
import com.decisionhub.backend.dto.*; import com.decisionhub.backend.entity.User; import com.decisionhub.backend.repository.*; import com.decisionhub.backend.service.*; import org.springframework.stereotype.Service;
@Service public class UserProfileServiceImpl implements UserProfileService { private final CurrentUserService current; private final UserRepository users; private final DecisionRepository decisions; private final VoteRepository votes; private final CommunityRepository communities; public UserProfileServiceImpl(CurrentUserService current, UserRepository users, DecisionRepository decisions, VoteRepository votes, CommunityRepository communities){this.current=current;this.users=users;this.decisions=decisions;this.votes=votes;this.communities=communities;} public ProfileResponse get(){return response(current.get());} public ProfileResponse update(ProfileUpdateRequest req){User u=current.get();u.setName(req.getName().trim()); return response(users.save(u));} private ProfileResponse response(User u){return ProfileResponse.builder().name(u.getName()).email(u.getEmail()).role(u.getRole().name()).createdAt(u.getCreatedAt()).decisionsCreated(decisions.countByCreatedBy(u)).votesParticipated(votes.countByUser(u)).joinedCommunities(communities.findAll().stream().filter(c->c.getMembers().stream().anyMatch(m->m.getId().equals(u.getId()))).count()).build();} }
